function shortestRun(values, target) {
  let best = Infinity
  let sum = 0
  let left = 0
  for (let right = 0; right < values.length; right++) {
    sum += values[right]
    while (sum >= target) {
      best = Math.min(best, right - left + 1)
      sum -= values[left++]
    }
  }
  return best === Infinity ? 0 : best
}
